-- root:       public.reg040_people
-- take:       200
-- expect:     ok
-- found:      ADR-015 (T-0302), not a torture schema: the residual scan
--             used to confirm a hit in a masked column by asking whether
--             the source COLUMN held the value anywhere, so a masked name
--             that equalled some other row's real name refused a correct
--             run at exit 9 (verify.refused.residual). That is why
--             mask/words.go's RoleGiven and RoleFamily lists were synthetic
--             until T-0304 (T-0287, T-0292): any real-name list over any
--             real name column of a few hundred rows produces such a
--             coincidence.
-- why:        every first_name and last_name here is a word of the masker's
--             own lists -- since T-0304 the 2020 Census given names and
--             surnames (mask/words_corpus.go) -- so a large share of
--             masked values equal another row's real value in the same
--             column, by construction. Since T-0302 the residual scan
--             explains such a hit instead of probing it -- the list contains
--             the value (mask.Emits), the target holds it no more often than
--             transform emitted it (Residual.Emitted), and the row check by
--             identity finds no source row that still holds its own value --
--             and reports verify.residual.explained as a count. reg040_people
--             has a primary key; reg040_people_twin has none (its identity is
--             the planner's pseudo-key over its NOT NULL foreign key), and
--             both must load clean. `not-copied:` is deliberately absent: a
--             masked name equal to another row's real name is the correct
--             outcome here, and that key greps the whole target for every
--             source value. The rows themselves are checked by I2's
--             ADR-015 half in the invariant suite and by
--             internal/verify's TestVerifyExplainsNameListCoincidences.

CREATE TABLE public.reg040_people (
    person_id  bigint PRIMARY KEY,
    first_name text NOT NULL,
    last_name  text NOT NULL,
    email      text NOT NULL
);

CREATE TABLE public.reg040_people_twin (
    person_id  bigint NOT NULL REFERENCES public.reg040_people (person_id),
    first_name text NOT NULL,
    last_name  text NOT NULL
);


